import * as THREE from './vendor/three.module.js';
import {ModernGameplay} from './modern-gameplay.js';
import {pointInside} from './core.js';
import {resolveHospital} from './hospital-rooftop-easter-egg.js';

const ELEVATOR_COUNT=5, RIDE_TIME=1.9, CALL_TIME=.55;
const states=new WeakMap();
let live=null,prompt=null;
const mats=new Map();
function material(c,glass=false,glow=false){const k=c+glass+glow;if(!mats.has(k))mats.set(k,new THREE.MeshStandardMaterial({color:c,roughness:.48,metalness:.18,transparent:glass,opacity:glass?.18:1,depthWrite:!glass,emissive:glow?c:'#000',emissiveIntensity:glow?.6:0,side:THREE.DoubleSide}));return mats.get(k);}
function block(root,c,x,y,z,w,h,d,yaw=0,glass=false){const m=new THREE.Mesh(new THREE.BoxGeometry(1,1,1),material(c,glass));m.position.set(x,y,z);m.scale.set(w,h,d);m.rotation.y=yaw;m.receiveShadow=true;root.add(m);return m;}
function area(poly){let a=0;for(let i=0;i<poly.length;i++){const p=poly[i],q=poly[(i+1)%poly.length];a+=p[0]*q[1]-q[0]*p[1];}return a*.5;}
function candidates(poly){const o=Math.sign(area(poly))||1,out=[];for(let i=0;i<poly.length;i++){const a=poly[i],b=poly[(i+1)%poly.length],dx=b[0]-a[0],dz=b[1]-a[1],len=Math.hypot(dx,dz);if(len<6)continue;let ix=-dz/len*o,iz=dx/len*o;const mx=(a[0]+b[0])/2,mz=(a[1]+b[1])/2;if(!pointInside(mx+ix,mz+iz,poly)){ix=-ix;iz=-iz;}const inside={x:mx+ix*3.2,z:mz+iz*3.2},outside={x:mx-ix*3,z:mz-iz*3};if(pointInside(inside.x,inside.z,poly)&&!pointInside(outside.x,outside.z,poly))out.push({inside,outside,len,yaw:Math.atan2(dx,dz),ix,iz});}return out;}
function chooseCandidates(poly,count=ELEVATOR_COUNT){const pool=candidates(poly),picked=[];while(pool.length&&picked.length<count){let best=null,score=-1;for(const c of pool){const space=picked.length?Math.min(...picked.map(p=>Math.hypot(c.outside.x-p.outside.x,c.outside.z-p.outside.z))):100;const s=Math.min(space,100)+Math.min(c.len,45)*.5;if(s>score){score=s;best=c;}}picked.push(best);pool.splice(pool.indexOf(best),1);}return picked;}
function sign(text){const c=document.createElement('canvas');c.width=512;c.height=112;const x=c.getContext('2d');x.fillStyle='#12343d';x.fillRect(0,0,512,112);x.strokeStyle='#e2bd62';x.lineWidth=7;x.strokeRect(4,4,504,104);x.fillStyle='#fff3c4';x.font='800 35px system-ui';x.textAlign='center';x.textBaseline='middle';x.fillText(text,256,57);const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;return new THREE.Mesh(new THREE.PlaneGeometry(5.4,1.18),new THREE.MeshBasicMaterial({map:t,transparent:true,side:THREE.DoubleSide,toneMapped:false}));}
function makeLift(game,site,c,i){const groundY=game.terrain.height(c.outside.x,c.outside.z),roofY=site.roofY,h=Math.max(8,roofY-groundY+.8),root=new THREE.Group();root.name='Monoblocco elevator '+(i+1);const frame='#344b53',glass='#76b7c8';for(const sx of [-1,1])for(const sz of [-1,1])block(root,frame,c.outside.x+sx*2,groundY+h/2,c.outside.z+sz*2,.22,h,.22,c.yaw);block(root,glass,c.outside.x,groundY+h/2,c.outside.z,4.3,h,4.3,c.yaw,true);block(root,'#17343d',c.outside.x,groundY+.08,c.outside.z,4.7,.16,4.7,c.yaw);block(root,'#17343d',c.outside.x,roofY+.08,c.outside.z,4.7,.16,4.7,c.yaw);
 const dx=c.inside.x-c.outside.x,dz=c.inside.z-c.outside.z,len=Math.hypot(dx,dz)+.8,yaw=Math.atan2(dx,dz),mx=(c.inside.x+c.outside.x)/2,mz=(c.inside.z+c.outside.z)/2;block(root,'#87969b',mx,roofY+.1,mz,3.5,.2,len,yaw);for(const side of [-1,1]){const nx=Math.cos(yaw),nz=-Math.sin(yaw);block(root,frame,mx+nx*side*1.65,roofY+.7,mz+nz*side*1.65,.12,1.2,len,yaw);}
 const a=sign('ASCENSORE · PISTA MOTO');a.position.set(c.outside.x,groundY+3.5,c.outside.z);a.rotation.y=c.yaw;root.add(a);const b=sign('ASCENSORE · USCITA');b.position.set(c.inside.x,roofY+2.1,c.inside.z);b.rotation.y=c.yaw+Math.PI;root.add(b);
 const cabin=new THREE.Group();cabin.name='Monoblocco elevator cabin '+(i+1);block(cabin,'#263f47',0,0,0,3.1,.16,3.1);block(cabin,glass,0,1.25,0,3.1,2.4,3.1,0,true);for(const sx of [-1,1])for(const sz of [-1,1])block(cabin,frame,sx*1.45,1.25,sz*1.45,.14,2.5,.14);cabin.position.set(c.outside.x,groundY+.16,c.outside.z);root.add(cabin);game.scene.add(root);return {root,cabin,groundY,roofY,cabinY:groundY+.16,ground:c.outside,roof:c.inside,exit:{x:c.outside.x-c.ix*2.6,z:c.outside.z-c.iz*2.6},yaw:c.yaw,travel:null};}
function install(game){const old=states.get(game);if(old)for(const e of old.elevators)e.root.parent?.remove(e.root);const site=resolveHospital(game);if(!site)return null;const chosen=chooseCandidates(site.polygon);if(chosen.length<5)console.warn('[Monoblocco elevators] '+chosen.length+'/5 safe positions found');const state={site,elevators:chosen.map((c,i)=>makeLift(game,site,c,i))};states.set(game,state);game.hospitalElevators=state;return state;}
function dist(a,b){return Math.hypot(a.x-b.x,a.z-b.z);}
function bike(game){const c=game.state.car;return game.state.mode==='car'&&c&&(c.spec?.bike||c.spec?.width<1.25||['motorcycle','scooter','cruiser'].includes(c.style));}
function nearby(game){const st=states.get(game),s=game.state;if(!st||!s?.started||s.paused||document.querySelector('dialog[open]'))return null;let best=null,d=Infinity;for(const e of st.elevators){const gd=dist(s,e.ground),rd=dist(s,e.roof),g=Math.abs(s.y-e.groundY)<3.5&&gd<5.5,r=Math.abs(s.y-e.roofY)<3&&rd<5.8;if(!g&&!r)continue;const q=g?gd:rd;if(q<d){d=q;best={e,from:r?'roof':'ground'};}}return best;}
function character(game){return game.scene.children.find(o=>o.userData?.character===game.state.character);}
function place(game,x,y,z,yaw){const s=game.state,c=s.mode==='car'?s.car:null;Object.assign(s,{x,y,z,yaw,speed:0,vy:0,parachuting:false});if(c){Object.assign(c,{x,y,z,yaw,speed:0,parked:false,missionUnit:true,budgetSleeping:false});c.mesh.visible=true;game.pose?.(c);}else{const p=character(game);if(p){p.visible=true;p.position.set(x,y+.08,z);p.rotation.y=yaw;}}}
function begin(game){const n=nearby(game);if(!n)return false;if(game.state.mode==='car'&&!bike(game)){game.toast?.('Ascensore Monoblocco: accesso consentito a piedi o in moto.',4);return true;}const e=n.e;if(e.travel)return true;const up=n.from==='ground',source=up?e.groundY+.16:e.roofY+.16,target=up?e.roofY+.16:e.groundY+.16;e.travel={phase:'call',start:game.state.elapsed,source,target,up};place(game,e.ground.x,source+.03,e.ground.z,e.yaw);game.toast?.(up?'Ascensore · salita alla pista moto.':'Ascensore · discesa al piano terra.',2.5);return true;}
const smooth=t=>t*t*(3-2*t);
function move(game,e){const t=e.travel;if(!t)return;const now=game.state.elapsed;if(t.phase==='call'){const u=Math.min(1,(now-t.start)/CALL_TIME),y=e.cabinY+(t.source-e.cabinY)*smooth(u);e.cabin.position.y=y;place(game,e.ground.x,t.source+.03,e.ground.z,e.yaw);if(u>=1){e.cabinY=t.source;t.phase='ride';t.start=now;}return;}const u=Math.min(1,(now-t.start)/RIDE_TIME),y=t.source+(t.target-t.source)*smooth(u);e.cabin.position.y=y;place(game,e.ground.x,y+.04,e.ground.z,e.yaw);if(u>=1){const p=t.up?e.roof:e.exit,py=t.up?e.roofY+.22:e.groundY+.18;place(game,p.x,py,p.z,e.yaw);e.cabinY=t.target;e.cabin.position.y=t.target;e.travel=null;game.toast?.(t.up?'Pista moto Monoblocco · sei sul tetto.':'Piano terra · ascensore Monoblocco.',3);}}
function ensurePrompt(){if(prompt)return;const style=document.createElement('style');style.textContent='#hospitalElevatorPrompt:not([hidden]){position:fixed;left:50%;bottom:108px;transform:translateX(-50%);z-index:82;background:#102d35ef;color:#fff4cc;border:2px solid #e3c66f;border-radius:12px;padding:11px 17px;font:800 14px system-ui;box-shadow:0 8px 26px #0008}';document.head.appendChild(style);prompt=document.createElement('button');prompt.id='hospitalElevatorPrompt';prompt.type='button';prompt.hidden=true;prompt.onclick=()=>live&&begin(live);document.body.appendChild(prompt);}
function update(game){live=game;ensurePrompt();const st=states.get(game);if(!st)return;for(const e of st.elevators){e.root.visible=dist(game.state,e.ground)<950;move(game,e);}const n=nearby(game),busy=st.elevators.some(e=>e.travel);prompt.hidden=!n||busy;if(n&&!busy)prompt.textContent=n.from==='ground'?'E · ASCENSORE → PISTA MOTO':'E · ASCENSORE → PIANO TERRA';}
const populate=ModernGameplay.prototype.populate,baseUpdate=ModernGameplay.prototype.update;if(!ModernGameplay.prototype.__hospitalRooftopElevators){ModernGameplay.prototype.__hospitalRooftopElevators=true;ModernGameplay.prototype.populate=function(...args){const r=populate.apply(this,args);install(this);return r;};ModernGameplay.prototype.update=function(dt){const r=baseUpdate.call(this,dt);update(this);return r;};}
window.addEventListener('keydown',e=>{if(e.code!=='KeyE'||e.repeat||!live||!nearby(live))return;if(begin(live)){e.preventDefault();e.stopImmediatePropagation();}},true);
export {ELEVATOR_COUNT,chooseCandidates};
